float musicalAccent(float value) {
 return clamp(value,0.0,1.0);
}

void mainImage(out vec4 fragColor,in vec2 fragCoord) {
 vec2 p=(2.0*fragCoord-iResolution.xy)/iResolution.y;
 float aspect=iResolution.x/iResolution.y, phase=vrchPhase_speed();
 float hit=musicalAccent(uParam_accent), influence=uParam_presence;
 vec2 center=clamp(vec2(uParam_hand_x,uParam_hand_y)/max(influence,.001),vec2(0.0),vec2(1.0));
 vec2 hand=(center*2.0-1.0)*vec2(aspect,1.0);
 float pull=exp(-pow(abs((p.x-hand.x)/.95),2.0))*hand.y*influence*.65;
 vec3 color=vec3(.003,.005,.014);
 float envelope=exp(-pow(abs(p.x/(aspect*.96+.2)),6.0));
 // Strand-independent terms: two wave families, one twist and one fan width.
 float sx=p.x-hand.x*influence*.65;
 float waveA=.29*sin(sx*1.45+phase*.44),waveB=.29*sin(sx*1.45+phase*.44+2.25);
 float twist=uParam_twist*sin(p.x*1.65-phase*.35);
 float fanWidth=uParam_width*.57*(.8+.42*cos(p.x*1.1+phase*.22))*cos(twist);
 // Per-strand angles advance by fixed steps; rotate their (cos, sin) pairs.
 float a0=p.x*1.4+phase*.44-.25,b0=p.x*1.1-phase*.55;
 vec2 tilt=vec2(cos(a0),sin(a0)),tiltStep=vec2(cos(.05),sin(.05));
 vec2 shine=vec2(cos(b0),sin(b0)),shineStep=vec2(cos(.36),sin(.36));
 for(int i=0;i<11;i++) {
  float index=float(i), f=index/10.0, side=f-.5;
  float wave=index>5.5?waveB:waveA;
  float strand=mod(index,6.0)/5.0-.5;
  float center=wave+strand*fanWidth+pull+side*influence*hand.x*.18;
  float slope=.44*tilt.x;
  float d=(p.y-center)*inversesqrt(1.0+slope*slope);
  float thickness=.013+.012*(1.0-abs(side)*1.2);
  float u=d/thickness,v=u/4.3;
  float silk=exp(-u*u);
  float haze=exp(-v*v);
  float lit=.5+.5*shine.x;
  float face=.48+.52*lit*lit*lit;
  tilt=vec2(tilt.x*tiltStep.x-tilt.y*tiltStep.y,tilt.y*tiltStep.x+tilt.x*tiltStep.y);
  shine=vec2(shine.x*shineStep.x-shine.y*shineStep.y,shine.y*shineStep.x+shine.x*shineStep.y);
  vec3 hue=mix(vec3(.014,.40,.49),vec3(.58,.11,.085),smoothstep(.2,.85,f));
  hue=mix(hue,uParam_tint.rgb,.28);
  color+=hue*silk*envelope*(.58+uParam_light*face+hit*face*.7);
  color+=hue*haze*envelope*.038*uParam_light;
 }
 float aura=exp(-pow(abs(p.y-.10*sin(p.x+phase*.2)),2.0)/.25)*envelope;
 color+=vec3(.007,.006,.025)*aura;
 fragColor=vec4(1.0-exp(-color*1.35),1.0);
}
